def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform full-length rows/columns mark the tile dividers.
    uniform_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    uniform_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    dividers = [grid[r][0] for r in uniform_rows] + [grid[0][c] for c in uniform_cols]
    divider = max(set(dividers), key=dividers.count)
    rows = [r for r in uniform_rows if grid[r][0] == divider]
    cols = [c for c in uniform_cols if grid[0][c] == divider]
    rb, cb = [-1] + rows + [h], [-1] + cols + [w]

    # The most common non-divider color is the tile background.
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v != divider)
    background = counts.most_common(1)[0][0]

    # Collect motif cells by their offset within a tile.
    motif = {}
    for i in range(len(rb) - 1):
        for j in range(len(cb) - 1):
            r0, r1 = rb[i] + 1, rb[i + 1]
            c0, c1 = cb[j] + 1, cb[j + 1]
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v != background and v != divider:
                        motif[(r - r0, c - c0)] = v

    out = [row[:] for row in grid]
    for i in range(len(rb) - 1):
        for j in range(len(cb) - 1):
            r0, r1 = rb[i] + 1, rb[i + 1]
            c0, c1 = cb[j] + 1, cb[j + 1]
            for (dr, dc), v in motif.items():
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = v
    return out
